{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function app allows HTTP traffic (HTTPS Only not enforced)",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The resource does not set `https_only = true`, allowing data to be transmitted over unencrypted HTTP, which exposes sensitive information and credentials in transit."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Outdated TLS/HTTP Version configuration",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The `site_config` block is missing, meaning the function app defaults to older or unspecified minimum TLS versions. Explicitly setting `minimum_tls_version` to '1.2' ensures modern encryption standards are used."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Authentication disabled for Function App",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The `auth_settings` block is missing, leaving the function app endpoints publicly accessible without identity verification. Enabling authentication restricts access to authorized users only."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  https_only                 = true\n\n  site_config {\n    minimum_tls_version = \"1.2\"\n  }\n\n  auth_settings {\n    enabled         = true\n    default_provider = \"AzureActiveDirectory\"\n\n    active_directory {\n      client_id     = \"<your-client-id>\"\n      tenant_id     = \"<your-tenant-id>\"\n    }\n  }\n}",
  "fix_summary": "Added `https_only = true` to enforce HTTPS, added a `site_config` block with `minimum_tls_version = \"1.2\"` to ensure secure transport protocols, and added an `auth_settings` block enabling Azure Active Directory authentication to prevent unauthorized public access."
}
